/**
 * The live-surface TABLE against the ASSETS it names.
 *
 * Wireup's `pnpm verify:3d-live` proves the table's signals have real producers
 * in the simulator source and that its `spec` anchors name features the CAD spec
 * has. What it cannot see is whether the 3D asset the scene actually loads
 * carries that feature: a generated GLB names its materials `Mat_<feature>`,
 * a hand-reviewed GLB names its own nodes, and the scene resolves whichever it
 * finds. A mismatch is the silent failure mode — the surface simply is not
 * drawn.
 *
 * This test closes that gap by reading the real files in `public/`:
 *
 *   • `/live-surfaces.json`   — the table (generated by Wireup);
 *   • `/cad-catalog.json`     — the specs the `spec` frame resolves against;
 *   • `/models3d/manifest.json` and the GLB each key maps to.
 *
 * It also runs `resolveAnchor` from the scene for every surface, against a
 * synthetic model built the way the asset pipeline builds one, so the anchor
 * code itself is exercised rather than assumed.
 */

import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';

import { beforeAll, describe, expect, it, vi } from 'vitest';
import { Box3, BoxGeometry, Group, Mesh, MeshStandardMaterial, Vector3 } from 'three';

import { loadParametricForKeys } from '../scene3d/cadCatalog';
import { resolveAnchor } from '../scene3d/live/anchors';
import type { LoadedModel } from '../scene3d/models3d';
import type { CadComponentSpec } from '../scene3d/cadTypes';
import type { LiveAnchor, LiveSurface, LiveSurfaceManifest } from '../scene3d/live/surfaceTypes';

const PUBLIC = join(__dirname, '..', '..', 'public');
const MODELS = join(PUBLIC, 'models3d');

/**
 * A canvas that exists but draws nothing.
 *
 * The parametric builder bakes a silkscreen texture through a 2D canvas; this
 * test is about GEOMETRY (where a panel lands, how big it is), so the canvas
 * only has to exist for the builder to run headlessly.
 */
function stubCanvas(): void {
  const context = new Proxy(
    {},
    {
      get: (_target, prop) => {
        if (prop === 'measureText') return () => ({ width: 12 });
        if (prop === 'createLinearGradient' || prop === 'createRadialGradient') {
          return () => ({ addColorStop: () => undefined });
        }
        if (prop === 'canvas') return { width: 0, height: 0 };
        return () => undefined;
      },
      set: () => true,
    },
  );
  vi.stubGlobal('document', {
    createElement: (tag: string) =>
      tag === 'canvas' ? { width: 0, height: 0, style: {}, getContext: () => context } : {},
    getElementById: () => null,
  });
}

// The parametric builder and the catalogue loader fetch from the site root;
// in a node test the `public/` directory IS the site root.
beforeAll(() => {
  stubCanvas();
  vi.stubGlobal('fetch', async (input: string | URL) => {
    const url = String(input);
    if (!url.startsWith('/')) return { ok: false, json: async () => null, status: 404 } as Response;
    const file = join(PUBLIC, url.slice(1));
    if (!existsSync(file)) return { ok: false, json: async () => null, status: 404 } as Response;
    return {
      ok: true,
      status: 200,
      json: async () => JSON.parse(readFileSync(file, 'utf-8')),
    } as Response;
  });
});

const manifest = JSON.parse(readFileSync(join(PUBLIC, 'live-surfaces.json'), 'utf-8')) as LiveSurfaceManifest;
const catalog = JSON.parse(readFileSync(join(PUBLIC, 'cad-catalog.json'), 'utf-8')) as {
  entries: Record<string, { cadOnly?: boolean; spec: CadComponentSpec }>;
};
const models = JSON.parse(readFileSync(join(MODELS, 'manifest.json'), 'utf-8')) as {
  models: Record<string, { file: string }>;
};

interface GlbNames {
  materials: Set<string>;
  nodes: Set<string>;
}

/** Names inside a GLB's JSON chunk (materials + nodes), or null if unreadable. */
function glbNames(file: string): GlbNames | null {
  try {
    const buf = readFileSync(file);
    if (buf.readUInt32LE(0) !== 0x46546c67) return null; // 'glTF'
    const chunkLength = buf.readUInt32LE(12);
    const chunkType = buf.readUInt32LE(16);
    if (chunkType !== 0x4e4f534a) return null; // 'JSON'
    const json = JSON.parse(buf.subarray(20, 20 + chunkLength).toString('utf-8')) as {
      materials?: { name?: string }[];
      nodes?: { name?: string }[];
    };
    return {
      materials: new Set((json.materials ?? []).map((entry) => entry.name ?? '')),
      nodes: new Set((json.nodes ?? []).map((entry) => entry.name ?? '')),
    };
  } catch {
    return null;
  }
}

const surfacesOf = (): { key: string; surface: LiveSurface }[] => {
  const out: { key: string; surface: LiveSurface }[] = [];
  for (const [key, part] of Object.entries(manifest.parts)) {
    for (const surface of part.surfaces ?? []) out.push({ key, surface });
  }
  return out;
};

/** A model shaped like a generated GLB: one mesh per feature, `Mat_<name>`. */
function syntheticModel(spec: CadComponentSpec): Group {
  const group = new Group();
  for (const feature of spec.features ?? []) {
    const material = new MeshStandardMaterial({ name: `Mat_${feature.name}` });
    const [width, height, depth] = feature.dimensions;
    // Real geometry, sized from the spec, so bounding-box anchors (bodyTop) and
    // the panel sizing behave exactly as they do on the loaded asset.
    const mesh = new Mesh(
      new BoxGeometry(Math.max(width, 0.1), Math.max(height, 0.1), Math.max(depth, 0.1)),
      material,
    );
    mesh.name = feature.name;
    mesh.userData.cadFeature = { name: feature.name, type: feature.type };
    mesh.position.set(feature.position[0], feature.position[1], feature.position[2]);
    group.add(mesh);
  }
  return group;
}

describe('live-surfaces.json against the catalog and the models', () => {
  it('covers the catalog key space exactly (driven or declared inert)', () => {
    const keys = Object.keys(catalog.entries).sort();
    const covered = [...Object.keys(manifest.parts), ...Object.keys(manifest.noLiveState)].sort();
    expect(covered).toEqual(keys);
    for (const key of Object.keys(manifest.parts)) {
      expect(manifest.parts[key]?.surfaces?.length ?? 0).toBeGreaterThan(0);
      expect(manifest.noLiveState[key]).toBeUndefined();
    }
    for (const key of Object.keys(manifest.noLiveState)) {
      expect((manifest.noLiveState[key] ?? '').trim().length).toBeGreaterThan(16);
    }
  });

  it('names only catalog keys, with the tag and provenance the catalog allocates', () => {
    for (const [key, part] of Object.entries(manifest.parts)) {
      const entry = catalog.entries[key];
      expect(entry, `"${key}" is not a CAD key`).toBeDefined();
      const tag = part.tag;
      expect(tag, `"${key}" has no tag`).toBeTruthy();
      if (entry.cadOnly) expect(tag).toBe('velxio-cad-bench-part');
      else expect(tag?.startsWith('wokwi-') || tag?.startsWith('velxio-')).toBe(true);
    }
  });

  it('resolves every anchor against the spec and a generated-style model', () => {
    const degenerate: string[] = [];
    for (const { key, surface } of surfacesOf()) {
      const spec = catalog.entries[key]?.spec;
      expect(spec, `"${key}" has no spec`).toBeDefined();
      const model = syntheticModel(spec as CadComponentSpec);
      const bounds = new Box3().setFromObject(model);
      const resolved = resolveAnchor(surface.anchor, model, {
        spec,
        recenter: new Vector3(),
        bounds,
      });
      expect(resolved, `"${key}" surface "${surface.id}" (${surface.kind}) did not resolve`).not.toBeNull();
      // A surface that paints a PANEL needs a real footprint; a cylinder's third
      // spec dimension is 0 by construction (diameter × height ≈ width × depth),
      // which is why motion/emissive/readout only need a width.
      const needsPlane = !['motion', 'emissive', 'readout'].includes(surface.kind);
      const width = resolved?.width ?? 0;
      const depth = resolved?.depth ?? 0;
      if (width <= 0 || (needsPlane && depth <= 0)) {
        degenerate.push(`${key}/${surface.id} (${surface.kind}) → ${resolved?.mode} ${width}×${depth}`);
      }

      // A surface that drives geometry must have something to drive: the scene
      // skips a motion/emissive whose anchor named no object or material.
      if (surface.kind === 'motion') expect(resolved?.target, `"${key}" ${surface.id}: no motion target`).toBeTruthy();
      if (surface.kind === 'emissive') {
        expect(resolved?.material, `"${key}" ${surface.id}: no emissive material`).toBeTruthy();
        expect(resolved?.material).toBeInstanceOf(MeshStandardMaterial);
      }
    }
    expect(degenerate).toEqual([]);
  });

  it('names a feature the key’s own GLB actually carries', () => {
    const missing: string[] = [];
    for (const { key, surface } of surfacesOf()) {
      const anchor: LiveAnchor = surface.anchor;
      const file = models.models[key]?.file;
      if (!file) continue;
      const names = glbNames(join(MODELS, file));
      if (!names) continue; // reviewed/absent asset: nothing to assert here
      const wanted = anchor.feature ?? anchor.node;
      if (!wanted) continue;
      // A spec-frame selector may be a feature TYPE (`heatsink`): the scene
      // resolves it to the spec feature's own NAME and then to that name's
      // material, so the check does the same rather than reading the type raw.
      const feature = (catalog.entries[key]?.spec.features ?? []).find(
        (entry) => entry.type === wanted || entry.name === wanted,
      );
      const candidates = [wanted, feature?.name].filter((name): name is string => Boolean(name));
      const found = candidates.some(
        (name) => names.materials.has(`Mat_${name}`) || names.materials.has(name) || names.nodes.has(name),
      );
      if (!found) missing.push(`${key} → "${wanted}" (${candidates.join(' | ')}) not in ${file}`);
    }
    expect(missing).toEqual([]);
  });

  it('places every surface on the REAL parametric model the scene renders', async () => {
    // The synthetic check above proves the spec arithmetic; this one runs the
    // same code the 3D scene runs (`loadParametricForKeys` → the assembly the
    // viewer builds), so a surface that would float off the part, or a panel
    // that would dwarf it, fails here instead of in the user's viewport.
    const keys = Object.keys(manifest.parts);
    const models: Map<string, LoadedModel> = await loadParametricForKeys(keys);
    const problems: string[] = [];

    for (const [key, part] of Object.entries(manifest.parts)) {
      const model = models.get(key);
      if (!model) {
        problems.push(`${key}: the parametric assembly did not build`);
        continue;
      }
      const bounds = model.bounds ?? new Box3().setFromObject(model.group);
      if (bounds.isEmpty()) {
        problems.push(`${key}: the assembly has no geometry`);
        continue;
      }
      const size = bounds.getSize(new Vector3());
      const maxSpan = Math.max(size.x, size.y, size.z);
      const slack = maxSpan * 0.3 + 25; // millimetres of legitimate overhang
      const spec = catalog.entries[key]?.spec;

      for (const surface of part.surfaces ?? []) {
        const resolved = resolveAnchor(surface.anchor, model.group, {
          spec,
          recenter: model.recenter,
          bounds,
        });
        if (!resolved) {
          problems.push(`${key}/${surface.id}: did not resolve on the real model`);
          continue;
        }
        const { position, width } = resolved;
        const outside =
          position.x < bounds.min.x - slack ||
          position.x > bounds.max.x + slack ||
          position.y < bounds.min.y - slack ||
          position.y > bounds.max.y + slack ||
          position.z < bounds.min.z - slack ||
          position.z > bounds.max.z + slack;
        if (outside) {
          problems.push(
            `${key}/${surface.id}: at (${position.x.toFixed(1)}, ${position.y.toFixed(1)}, ${position.z.toFixed(1)}) is outside the body ${bounds.min.toArray().map((n) => n.toFixed(1)).join(',')}…${bounds.max.toArray().map((n) => n.toFixed(1)).join(',')}`,
          );
        }
        // A plaque is a floating label (sized to its text on purpose); every
        // other surface is a panel on the part and must fit it.
        if (surface.kind !== 'readout' && width > maxSpan * 2.5 + 5) {
          problems.push(`${key}/${surface.id}: ${width.toFixed(1)} mm wide on a ${maxSpan.toFixed(1)} mm body`);
        }
      }
    }
    expect(problems).toEqual([]);
  });

  it('keeps every GLB the table depends on present', () => {
    const absent: string[] = [];
    for (const key of Object.keys(manifest.parts)) {
      const file = models.models[key]?.file;
      if (!file) {
        absent.push(`${key}: no model mapped`);
        continue;
      }
      try {
        readFileSync(join(MODELS, file));
      } catch {
        absent.push(`${key}: ${file} is missing`);
      }
    }
    expect(absent).toEqual([]);
  });
});
